#include <stdio.h>
#include <stdlib.h>

int main() {
  int *dynamic_array;  // Pointer to hold the address of dynamically allocated memory
  int array_size = 5;

  // Allocate memory for an array of 5 integers
  dynamic_array = (int *)malloc(array_size * sizeof(int));

  if (dynamic_array == NULL) {
    fprintf(stderr, "Memory allocation failed\n");
    return 1; // Indicate an error
  }

  // Initialize and use the dynamically allocated array
  for (int i = 0; i < array_size; i++) {
    dynamic_array[i] = i * 10;
  }

  for (int i = 0; i < array_size; i++) {
    printf("dynamic_array[%d] = %d\n", i, dynamic_array[i]);
  }

  // Release the dynamically allocated memory
  free(dynamic_array);
  dynamic_array = NULL; // Good practice to set the pointer to NULL after freeing

  return 0;
}
